set -Eeuo pipefail
CAMPAIGN=REPL_TROT_PAIRED_IK_v0.6.39
printf 'CAMPAIGN=%s\nLANE=TERMUX_GIT_SOURCE_ONLY\nCANONICAL_GLB_MUTATION=FORBIDDEN\n' "$CAMPAIGN"
printf 'LAUNCHER_SHA256=%s\n' "$(sha256sum "$0" | cut -d' ' -f1)"
